window.ROLES={"reception":{"label":"Lễ tân","emoji":"🛎️","scenarios":[{"k":"r_rc_walkin","l":"Khách vãng lai hỏi phòng","s":"You are a foreign traveller walking into the hotel without a booking at 10 p.m. Ask if there is a room tonight, the price and whether breakfast is included."},{"k":"r_rc_late","l":"Khách nhận phòng lúc nửa đêm","s":"You are a tired guest arriving at midnight after a delayed flight. Check in quickly and ask about room service and the Wi-Fi."},{"k":"r_rc_bill","l":"Thắc mắc hoá đơn","s":"You are a guest checking out who thinks the bill is too high. Ask about the minibar charge and the service charge, and stay polite but firm."},{"k":"r_rc_taxi","l":"Đặt xe & tour","s":"You are a guest who needs a taxi to the airport tomorrow at 5 a.m. and a day tour to Hội An the day after. Ask me to arrange both and ask the prices."}],"dialogues":[{"them":"Hello, do you have any rooms for tonight? I don't have a booking.","opts":[{"t":"Let me check for you. Yes, we have a double room for 1.4 million dong, including breakfast.","good":true,"fb":"Kiểm tra + loại phòng, giá, quyền lợi."},{"t":"Have. One million four.","good":false,"fb":"Thiếu chủ ngữ và đơn vị: 'Yes, we have a room. It's 1.4 million dong.'"},{"t":"No booking, cannot.","good":false,"fb":"Sai — khách vãng lai vẫn thuê được nếu còn phòng; lại cộc lốc."}]},{"them":"My key card doesn't work.","opts":[{"t":"You put it wrong.","good":false,"fb":"Đổ lỗi cho khách; luôn xin lỗi và làm lại thẻ."},{"t":"I'm sorry about that. Let me make you a new one. May I see your ID, please?","good":true,"fb":"Xin lỗi + làm lại thẻ + kiểm tra danh tính."},{"t":"Card is broken, I make new.","good":false,"fb":"Thiếu mạo từ và 'will': 'I'll make a new one for you.'"}]},{"them":"Could you keep my bags after I check out? My flight is at night.","opts":[{"t":"Yes, you leave here.","good":false,"fb":"Nghe như ra lệnh: 'Sure, you can leave them with us.'"},{"t":"Bags keep until what time?","good":false,"fb":"Dịch từng chữ, sai trật tự: 'What time will you pick them up?'"},{"t":"Of course. We'll keep them in the luggage room. Here's your ticket.","good":true,"fb":"Đồng ý + giữ ở đâu + đưa phiếu gửi đồ."}]},{"them":"Where can I change money?","opts":[{"t":"We can change US dollars here at the front desk, or there's a bank two minutes away.","good":true,"fb":"Đưa hai lựa chọn cụ thể."},{"t":"Change money at bank.","good":false,"fb":"Thiếu chủ ngữ và mạo từ; chưa nói ngân hàng ở đâu."},{"t":"Money in Vietnam is dong.","good":false,"fb":"Không trả lời câu hỏi đổi tiền ở đâu."}]},{"them":"Is there a gym in the hotel?","opts":[{"t":"Yes, have gym floor three.","good":false,"fb":"Thiếu chủ ngữ, sai cấu trúc: 'Yes, there's a gym on the third floor.'"},{"t":"Yes, it's on the third floor, next to the pool. It's open from 6 a.m. to 10 p.m.","good":true,"fb":"Vị trí + giờ mở cửa."},{"t":"Gym is free.","good":false,"fb":"Không nói có hay không, ở đâu."}]},{"them":"Can you call a taxi for me? I'm going to the airport.","opts":[{"t":"OK, you wait.","good":false,"fb":"Cộc lốc; nên nói bao lâu xe đến."},{"t":"Taxi is coming ten minutes.","good":false,"fb":"Thiếu 'in': 'The taxi will be here in ten minutes.'"},{"t":"Sure. It'll be here in about ten minutes. The fare is around 200,000 dong.","good":true,"fb":"Đồng ý + thời gian chờ + giá tham khảo."}]}]},"fnb":{"label":"Nhà hàng · Bar","emoji":"🍽️","scenarios":[{"k":"r_fb_seat","l":"Đón khách & xếp bàn","s":"You are a foreign couple arriving at the hotel restaurant without a booking on a busy night. Ask for a table by the window and ask how long you need to wait."},{"k":"r_fb_order","l":"Gọi món","s":"You are a hungry tourist who doesn't know Vietnamese food. Ask me to explain two dishes and recommend something not too spicy."},{"k":"r_fb_wrong","l":"Mang nhầm món","s":"You are a guest who got the wrong dish after waiting 30 minutes. Complain politely and ask what I can do."},{"k":"r_fb_bar","l":"Quầy bar","s":"You are a hotel guest at the bar in the evening. Ask about local beer, cocktails and happy hour, then ask to charge the drinks to your room."}],"dialogues":[{"them":"Can we sit outside?","opts":[{"t":"Outside is hot, inside better.","good":false,"fb":"Áp ý mình lên khách, thiếu động từ 'is'."},{"t":"Of course. This way, please. Would you like a table near the garden?","good":true,"fb":"Đồng ý + dẫn khách + gợi ý chỗ."},{"t":"Yes, you sit anywhere.","good":false,"fb":"Không dẫn khách, nghe thiếu chuyên nghiệp."}]},{"them":"What's in the spring rolls?","opts":[{"t":"Many things inside.","good":false,"fb":"Mơ hồ, khách không biết có gì (nguy hiểm nếu dị ứng)."},{"t":"Spring roll is Vietnamese food.","good":false,"fb":"Không trả lời câu hỏi về thành phần."},{"t":"They have pork, shrimp, vegetables and glass noodles. They come with a fish sauce dip.","good":true,"fb":"Liệt kê thành phần rõ ràng — quan trọng với khách dị ứng."}]},{"them":"Could I have a glass of water, please?","opts":[{"t":"Certainly. Still or sparkling?","good":true,"fb":"Đồng ý + hỏi loại nước — chuẩn nhà hàng."},{"t":"One water. OK.","good":false,"fb":"Cộc; nên nói 'Certainly' và hỏi loại nước."},{"t":"Water is not free.","good":false,"fb":"Nói thẳng quá; nếu tính phí thì báo giá lịch sự."}]},{"them":"Excuse me, we've been waiting for our food for 30 minutes.","opts":[{"t":"Kitchen is busy today.","good":false,"fb":"Chỉ giải thích, không xin lỗi, không có giải pháp."},{"t":"I'm very sorry. Let me check with the kitchen right now. It'll be out in a few minutes.","good":true,"fb":"Xin lỗi + kiểm tra + báo thời gian."},{"t":"Sorry, food coming soon.","good":false,"fb":"Thiếu 'the' và 'is'; 'soon' mơ hồ — nên nói bao nhiêu phút."}]},{"them":"Can I charge this to my room?","opts":[{"t":"Yes, room number?","good":false,"fb":"Hơi cộc; nên nói 'May I have your room number, please?'"},{"t":"You must pay cash here.","good":false,"fb":"Cứng nhắc và sai quy trình — khách lưu trú thường được ghi vào tiền phòng."},{"t":"Of course. May I have your room number, and could you sign here, please?","good":true,"fb":"Đồng ý + xin số phòng và chữ ký."}]},{"them":"That was delicious, thank you!","opts":[{"t":"I'm so glad you enjoyed it! I'll tell the chef.","good":true,"fb":"Vui vẻ đáp lời khen + chuyển lời cho bếp."},{"t":"Yes, I know.","good":false,"fb":"Nghe kiêu, không cảm ơn."},{"t":"Thank you, you are welcome.","good":false,"fb":"Lẫn lộn: 'You're welcome' dùng để đáp lời cảm ơn, không đáp lời khen."}]}]},"housekeeping":{"label":"Buồng phòng","emoji":"🧹","scenarios":[{"k":"r_hk_clean","l":"Dọn phòng khi khách có mặt","s":"You are a guest working in your room when I knock to clean it. Ask me to come back later and ask for fresh towels and bottled water."},{"k":"r_hk_broken","l":"Báo đồ hỏng","s":"You are a guest whose TV and hair dryer are not working. Tell me about the problems and ask when someone will repair them."},{"k":"r_hk_lost","l":"Đồ thất lạc","s":"You are a guest who left a phone charger in the room after checking out. Call housekeeping, describe it and ask how to get it back."},{"k":"r_hk_amenity","l":"Xin thêm đồ dùng","s":"You are a guest with a small child. Ask me for an extra blanket, more pillows, children's slippers and a kettle."}],"dialogues":[{"them":"Can you clean my room now? I'm going out.","opts":[{"t":"OK, I clean.","good":false,"fb":"Thiếu 'will' và tân ngữ: 'I'll clean it now.'"},{"t":"Now is not my time. Afternoon.","good":false,"fb":"Từ chối khách và dịch từng chữ."},{"t":"Of course. I'll clean it now, and it'll be ready in about thirty minutes.","good":true,"fb":"Đồng ý + thời gian hoàn thành."}]},{"them":"Could I get some more coffee and tea bags?","opts":[{"t":"Certainly. I'll bring some right away.","good":true,"fb":"Đồng ý + làm ngay."},{"t":"One day only two.","good":false,"fb":"Nêu quy định cộc lốc; nếu có giới hạn thì giải thích lịch sự."},{"t":"Yes, I bringing.","good":false,"fb":"Sai thì: 'I'll bring them.'"}]},{"them":"The TV isn't working.","opts":[{"t":"TV is old, sorry.","good":false,"fb":"Thừa nhận lỗi nhưng không xử lý."},{"t":"I'm sorry. Let me try the remote first. If it still doesn't work, I'll call maintenance.","good":true,"fb":"Xin lỗi + thử trước + phương án tiếp theo."},{"t":"Not my job.","good":false,"fb":"Đẩy trách nhiệm, rất thiếu chuyên nghiệp."}]},{"them":"Please don't change the towels every day. I want to save water.","opts":[{"t":"OK, no change.","good":false,"fb":"Cộc, thiếu lời cảm ơn."},{"t":"But hotel rule is change.","good":false,"fb":"Cứng nhắc; khách sạn thường khuyến khích tiết kiệm nước."},{"t":"Thank you, that's very kind. Just hang them up and we'll leave them.","good":true,"fb":"Cảm ơn + hướng dẫn treo khăn."}]},{"them":"I found a stain on the bed sheet.","opts":[{"t":"I'm so sorry. I'll change the sheets for you right now.","good":true,"fb":"Xin lỗi + thay ngay."},{"t":"It's not a stain, it's old.","good":false,"fb":"Cãi khách, không giải quyết."},{"t":"Sorry, I change tomorrow.","good":false,"fb":"Thiếu 'will' và hẹn quá lâu — nên thay ngay."}]},{"them":"Excuse me, what time do you usually clean the rooms?","opts":[{"t":"Morning, afternoon.","good":false,"fb":"Mơ hồ, không thành câu."},{"t":"Usually between 9 a.m. and 3 p.m. Would you like a special time?","good":true,"fb":"Khung giờ + hỏi yêu cầu riêng."},{"t":"We clean when you not here.","good":false,"fb":"Thiếu 'are': 'when you're not here' — lại không nói giờ."}]}]},"guide":{"label":"Hướng dẫn viên · Tour","emoji":"🗺️","scenarios":[{"k":"r_gd_start","l":"Mở đầu tour","s":"You are a tourist on my day tour. At the start, ask me about the plan for the day, lunch and when we will come back to the hotel."},{"k":"r_gd_history","l":"Hỏi về lịch sử","s":"You are a curious tourist in the old town of Hội An. Ask me about the history of the Japanese Bridge and why the town has so many lanterns."},{"k":"r_gd_late","l":"Khách về trễ điểm hẹn","s":"You are a tourist who came back to the bus 20 minutes late. Apologise and explain that you got lost at the market."},{"k":"r_gd_price","l":"Mặc cả & mua sắm","s":"You are a tourist at a market with me as your guide. Ask me how to bargain, what a fair price is and what souvenirs to buy."}],"dialogues":[{"them":"How long does the boat trip take?","opts":[{"t":"About three hours. We'll stop at a cave and a floating village.","good":true,"fb":"Thời gian + các điểm dừng."},{"t":"Three hour.","good":false,"fb":"Thiếu 's': 'three hours' — và nên nói thêm lịch trình."},{"t":"Not long, don't worry.","good":false,"fb":"Mơ hồ, khách cần con số cụ thể."}]},{"them":"Can I go to the toilet before we leave?","opts":[{"t":"Toilet there, quick.","good":false,"fb":"Cộc, giục khách."},{"t":"Of course. The toilets are next to the ticket office. We leave in ten minutes.","good":true,"fb":"Chỉ chỗ + nhắc giờ đi."},{"t":"You can go toilet.","good":false,"fb":"Thiếu 'to the': 'You can go to the toilet.'"}]},{"them":"What does this sign say?","opts":[{"t":"It say no shoes.","good":false,"fb":"Thiếu 's' ở 'says' và quá cụt."},{"t":"Vietnamese words, very difficult.","good":false,"fb":"Không giúp khách hiểu biển."},{"t":"It says, 'Please take off your shoes before entering the temple.'","good":true,"fb":"Dịch rõ nội dung biển."}]},{"them":"It's raining. Will the tour still go ahead?","opts":[{"t":"Yes, it will. We'll visit the indoor places first, and I have raincoats for everyone.","good":true,"fb":"Trả lời + điều chỉnh lịch trình + chuẩn bị áo mưa."},{"t":"Rain is no problem.","good":false,"fb":"Chủ quan, không nói phương án."},{"t":"Maybe yes, maybe no.","good":false,"fb":"Mơ hồ, khách không biết chuẩn bị gì."}]},{"them":"Is the tap water safe to drink?","opts":[{"t":"Yes, drink OK.","good":false,"fb":"Sai thông tin, nguy hiểm cho khách."},{"t":"I'm afraid not. Please drink bottled water. I have some for everyone on the bus.","good":true,"fb":"Cảnh báo + có sẵn giải pháp."},{"t":"Water is not clean, you buy.","good":false,"fb":"Thiếu mạo từ, nghe cộc; nên nói có nước đóng chai."}]},{"them":"Thank you so much for today. You were a great guide!","opts":[{"t":"Yes, I am a great guide.","good":false,"fb":"Nhận lời khen thiếu khiêm tốn, nghe kỳ."},{"t":"You're welcome. Tip, please.","good":false,"fb":"Đòi tiền boa, rất thiếu chuyên nghiệp."},{"t":"Thank you! It was a pleasure. I hope you enjoy the rest of your trip.","good":true,"fb":"Cảm ơn + chúc tiếp chuyến đi."}]}]}};
